const item = $input.item.json;
const body = item.body || item;

const title = body.title || 'Untitled Post';
const keyMessage = body.key_message || body.topic || '';
const mediaUrls = Array.isArray(body.media_urls) ? body.media_urls : (body.media_url ? [body.media_url] : []);
const targetPlatforms = Array.isArray(body.target_platforms) && body.target_platforms.length > 0 
  ? body.target_platforms 
  : ['linkedin', 'twitter', 'instagram'];
const scheduledFor = body.scheduled_for || null;

if (!keyMessage) {
  throw new Error("Missing 'key_message' in request payload.");
}

return {
  json: {
    post_id: body.id || ('post_' + Date.now()),
    title: title,
    key_message: keyMessage,
    media_urls: mediaUrls,
    target_platforms: targetPlatforms,
    scheduled_for: scheduledFor,
    started_at: Date.now()
  }
};

const inputData = $('Extract & Validate Input').item.json;
const llmResponse = $input.item.json;

let variants = {};
try {
  const content = llmResponse.choices[0].message.content;
  variants = JSON.parse(content);
} catch (e) {
  throw new Error("Failed to parse LLM variants JSON: " + e.message);
}

const validationErrors = [];

// 1. Validate X (Twitter) character limit
if (variants.twitter) {
  if (variants.twitter.length > 280) {
    // Truncate cleanly at word boundary
    variants.twitter = variants.twitter.substring(0, 275).replace(/\s+\S*$/, '') + '...';
  }
}

// 2. Validate Instagram media requirement
if (variants.instagram) {
  if (!inputData.media_urls || inputData.media_urls.length === 0) {
    validationErrors.push("Instagram requires at least one image or video URL. Text-only posting is unsupported.");
  }
  // Validate hashtag limit
  const hashtagCount = (variants.instagram.match(/#[a-zA-Z0-9_]+/g) || []).length;
  if (hashtagCount > 30) {
    validationErrors.push("Instagram post exceeds 30 hashtags (" + hashtagCount + " detected).");
  }
}

// 3. Validate LinkedIn length
if (variants.linkedin && variants.linkedin.length > 3000) {
  variants.linkedin = variants.linkedin.substring(0, 2990) + '...';
}

return {
  json: {
    ...inputData,
    variants: variants,
    is_valid: validationErrors.length === 0,
    validation_errors: validationErrors,
    status: validationErrors.length === 0 ? 'ready_for_approval' : 'validation_failed',
    generated_at: new Date().toISOString()
  }
};
